/* C ABI over the AOT-compiled Gated DeltaNet Triton kernels (Qwen3.5-0.8B linear-attention layer:
 * H = HV = 16 heads, K = V = 128, chunk 64, bf16 activations, fp32 state, g and beta computed upstream).
 * Spike code: throwaway evidence outside Roost.slnx. The launch grids and host-side chunk tables follow
 * flash-linear-attention's Python wrappers at the pinned commit; gdn_kernels.[ch] are generated by build_aot.py.
 * Stub indices (see manifest.json in the build output):
 *   00 l2norm | 01-06 non-varlen chunk path | 07-12 varlen chunk path | 13 recurrent | 14 recurrent varlen */
#include <stdint.h>
#include <stdlib.h>
#include "gdn_kernels.h"

#define NH 16
#define KD 128
#define VD 128
#define BTC 64

static unsigned cdiv(unsigned a, unsigned b) { return (a + b - 1) / b; }
static size_t align256(size_t x) { return (x + 255) & ~(size_t)255; }

/* Chunk tables for a packed batch: chunk_indices[NT][2] = (sequence, chunk-in-sequence), chunk_offsets[N+1]
 * (prefix count of chunks, int64). Returns NT. Host side, as prepare_chunk_indices/offsets in FLA. */
int gdn_make_chunk_tables(const int32_t *cu_seqlens, int n, int32_t *chunk_indices, int64_t *chunk_offsets) {
    int nt = 0;
    chunk_offsets[0] = 0;
    for (int s = 0; s < n; s++) {
        int len = cu_seqlens[s + 1] - cu_seqlens[s];
        int c = (len + BTC - 1) / BTC;
        for (int j = 0; j < c; j++) { chunk_indices[2 * nt] = s; chunk_indices[2 * nt + 1] = j; nt++; }
        chunk_offsets[s + 1] = nt;
    }
    return nt;
}

/* Scratch needed by gdn_chunk_prefill for t tokens in nt chunks. */
size_t gdn_chunk_workspace_bytes(int t, int nt) {
    size_t tok = (size_t)t;
    return align256(tok * NH * KD * 2) * 2          /* normalised q, k (bf16) */
         + align256(tok * NH * 4) * 2               /* rstd of q and k (fp32) */
         + align256(tok * NH * 4)                   /* chunk-local cumulative gate (fp32) */
         + align256(tok * NH * BTC * 2)             /* A = (I + KKT)^-1 (bf16) */
         + align256(tok * NH * KD * 2) * 2          /* w, u (bf16) */
         + align256(tok * NH * VD * 2)              /* v_new (bf16) */
         + align256((size_t)nt * NH * KD * VD * 2); /* per-chunk states h (bf16) */
}

/* Prefill for a packed batch (varlen != 0: n sequences, cu_seqlens/chunk tables on device) or one sequence
 * (varlen == 0: t tokens, n ignored). h0 may be 0. ht (fp32 [n][NH][KD][VD]) is always written. */
int gdn_chunk_prefill(CUstream st, int varlen, int n, int t, int nt,
                      CUdeviceptr q, CUdeviceptr k, CUdeviceptr v, CUdeviceptr g, CUdeviceptr beta,
                      CUdeviceptr h0, CUdeviceptr ht, CUdeviceptr o,
                      CUdeviceptr cu_seqlens, CUdeviceptr chunk_indices, CUdeviceptr chunk_offsets,
                      CUdeviceptr ws) {
    CUdeviceptr p = ws;
    #define TAKE(var, bytes) CUdeviceptr var = p; p += align256(bytes)
    TAKE(qn, (size_t)t * NH * KD * 2); TAKE(kn, (size_t)t * NH * KD * 2);
    TAKE(qr, (size_t)t * NH * 4);      TAKE(kr, (size_t)t * NH * 4);
    TAKE(gc, (size_t)t * NH * 4);      TAKE(A, (size_t)t * NH * BTC * 2);
    TAKE(w, (size_t)t * NH * KD * 2);  TAKE(u, (size_t)t * NH * VD * 2);
    TAKE(vn, (size_t)t * NH * VD * 2); TAKE(h, (size_t)nt * NH * KD * VD * 2);
    CUresult r;
    /* The fused kkt+solve kernel writes only the lower-triangular blocks of A and relies on FLA's torch.zeros
     * allocation for the rest; skipping this memset gives NaN from uninitialised memory. */
    if ((r = cuMemsetD8Async(A, 0, (size_t)t * NH * BTC * 2, st))) return r;
    const float scale = 0.08838834764831845f;      /* K^-0.5 */
    const float rcp_ln2 = 1.4426950216f;
    unsigned rows = (unsigned)t * NH;
    if ((r = gdn_00_l2norm_fwd_kernel(st, cdiv(rows, 16), 1, 1, q, qn, qr, 1e-6f, rows))) return r;
    if ((r = gdn_00_l2norm_fwd_kernel(st, cdiv(rows, 16), 1, 1, k, kn, kr, 1e-6f, rows))) return r;
    if (varlen) {
        if ((r = gdn_07_chunk_local_cumsum_scalar_kernel(st, nt * NH, 1, 1, g, gc, rcp_ln2, cu_seqlens, chunk_indices, t))) return r;
        if ((r = gdn_08_chunk_gated_delta_rule_fwd_kkt_solve_kernel(st, nt, NH, 1, kn, gc, beta, A, cu_seqlens, chunk_indices, t))) return r;
        if ((r = gdn_09_recompute_w_u_fwd_kernel(st, nt, NH, 1, kn, v, beta, w, u, A, gc, cu_seqlens, chunk_indices, t))) return r;
        if (h0) { if ((r = gdn_10_chunk_gated_delta_rule_fwd_kernel_h_blockdim64(st, 4 * n * NH, 1, 1, kn, u, w, vn, gc, h, h0, ht, cu_seqlens, chunk_offsets, t))) return r; }
        else    { if ((r = gdn_12_chunk_gated_delta_rule_fwd_kernel_h_blockdim64(st, 4 * n * NH, 1, 1, kn, u, w, vn, gc, h, ht, cu_seqlens, chunk_offsets, t))) return r; }
        return gdn_11_chunk_fwd_kernel_o(st, 4 * nt, NH, 1, qn, kn, vn, h, gc, o, cu_seqlens, chunk_indices, scale, t);
    }
    if ((r = gdn_01_chunk_local_cumsum_scalar_kernel(st, nt * NH, 1, 1, g, gc, rcp_ln2, t))) return r;
    if ((r = gdn_02_chunk_gated_delta_rule_fwd_kkt_solve_kernel(st, nt, NH, 1, kn, gc, beta, A, t))) return r;
    if ((r = gdn_03_recompute_w_u_fwd_kernel(st, nt, NH, 1, kn, v, beta, w, u, A, gc, t))) return r;
    if (h0) { if ((r = gdn_06_chunk_gated_delta_rule_fwd_kernel_h_blockdim64(st, 4 * NH, 1, 1, kn, u, w, vn, gc, h, h0, ht, t))) return r; }
    else    { if ((r = gdn_04_chunk_gated_delta_rule_fwd_kernel_h_blockdim64(st, 4 * NH, 1, 1, kn, u, w, vn, gc, h, ht, t))) return r; }
    return gdn_05_chunk_fwd_kernel_o(st, 4 * nt, NH, 1, qn, kn, vn, h, gc, o, scale, t);
}

/* Decode / short continuation with the recurrent kernel; q and k are l2-normalised in the kernel.
 * varlen != 0: n sequences packed with cu_seqlens (device); otherwise one sequence of t tokens. h0 required. */
int gdn_recurrent(CUstream st, int varlen, int n, int t,
                  CUdeviceptr q, CUdeviceptr k, CUdeviceptr v, CUdeviceptr g, CUdeviceptr beta,
                  CUdeviceptr h0, CUdeviceptr ht, CUdeviceptr o, CUdeviceptr cu_seqlens) {
    const float scale = 0.08838834764831845f;
    if (varlen) return gdn_14_fused_recurrent_gated_delta_rule_fwd_kernel(st, 16 * n * NH, 1, 1, q, k, v, g, beta, o, h0, ht, cu_seqlens, scale, t);
    return gdn_13_fused_recurrent_gated_delta_rule_fwd_kernel(st, 16 * NH, 1, 1, q, k, v, g, beta, o, h0, ht, scale, t);
}
